void Solver::rephase() {
    rephases = 0;
    threshold *= 0.8; // More aggressive reduction to trigger rephase earlier
    rephase_limit += 4096; // Smaller increment to allow more frequent rephasing
    // Update saved phases based on local best and random noise
    for (int i = 1; i <= vars; i++) {
        if (rand() % 100 < 70) saved[i] = local_best[i]; // 70% local best
        else if (rand() % 100 < 10) saved[i] = -local_best[i]; // 10% invert local best
        else saved[i] = rand() % 2 ? 1 : -1; // 20% random
    }
}
